static _R _dragByKeyHold(String method, Map<String, String> params) async {
  final keyValue = params['key'];
  if (keyValue == null || keyValue.isEmpty) {
    return _error('key parameter required');
  }
  final dx = double.tryParse(params['dx'] ?? '');
  final dy = double.tryParse(params['dy'] ?? '');
  if (dx == null || dy == null) {
    return _error('dx and dy parameters required (double)');
  }

  final steps = (int.tryParse(params['steps'] ?? '8') ?? 8).clamp(1, 120);
  final holdFraction =
      double.tryParse(params['holdFraction'] ?? '')?.clamp(0.0, 1.0);
  final holdSteps = (holdFraction == null
      ? (steps / 2).round()
      : (steps * holdFraction).round()).clamp(1, steps);

  final kindParam = (params['kind'] ?? '').toLowerCase();
  final pointerKind = switch (kindParam) {
    'touch' => PointerDeviceKind.touch,
    'mouse' => PointerDeviceKind.mouse,
    _ => (defaultTargetPlatform == TargetPlatform.macOS ||
            defaultTargetPlatform == TargetPlatform.linux ||
            defaultTargetPlatform == TargetPlatform.windows)
        ? PointerDeviceKind.mouse
        : PointerDeviceKind.touch,
  };

  final element = _findElementByKey(keyValue);
  if (element == null) {
    return _error('no widget found with key "$keyValue"');
  }

  final ro = element.findRenderObject();
  if (ro is! RenderBox || !ro.attached || !ro.hasSize || ro.size.isEmpty) {
    return _error('widget with key "$keyValue" has no usable RenderBox');
  }

  final binding = GestureBinding.instance;
  final start = ro.localToGlobal(ro.size.center(Offset.zero));

  _syntheticPointerSeq++;
  final pointer = 0x70000 | (_syntheticPointerSeq & 0xFFFF);
  final t0 = Duration(milliseconds: DateTime.now().millisecondsSinceEpoch);

  binding.handlePointerEvent(
    PointerAddedEvent(
      pointer: pointer,
      position: start,
      kind: pointerKind,
      timeStamp: t0,
    ),
  );
  binding.handlePointerEvent(
    PointerDownEvent(
      pointer: pointer,
      position: start,
      kind: pointerKind,
      buttons: kPrimaryButton,
      timeStamp: t0,
    ),
  );

  for (var i = 1; i <= holdSteps; i++) {
    final p = Offset(
      start.dx + (dx * i / steps),
      start.dy + (dy * i / steps),
    );
    final ts = t0 + Duration(milliseconds: 8 * i);
    binding.handlePointerEvent(
      PointerMoveEvent(
        pointer: pointer,
        position: p,
        kind: pointerKind,
        buttons: kPrimaryButton,
      timeStamp: ts,
      ),
    );
  }

  final current = Offset(
    start.dx + (dx * holdSteps / steps),
    start.dy + (dy * holdSteps / steps),
  );

  return _ok({
    'held': true,
    'dragged': keyValue,
    'pointer': pointer,
    'from': {'x': start.dx, 'y': start.dy},
    'to': {'x': current.dx, 'y': current.dy},
    'holdSteps': holdSteps,
    'steps': steps,
    'kind': pointerKind.name,
  });
}

static _R _endDrag(String method, Map<String, String> params) async {
  final pointer = int.tryParse(params['pointer'] ?? '');
  final x = double.tryParse(params['x'] ?? '');
  final y = double.tryParse(params['y'] ?? '');
  if (pointer == null || x == null || y == null) {
    return _error('pointer (int), x (double), and y (double) parameters required');
  }

  final binding = GestureBinding.instance;
  final tEnd = Duration(milliseconds: DateTime.now().millisecondsSinceEpoch);

  final position = Offset(x, y);

  binding.handlePointerEvent(
    PointerUpEvent(
      pointer: pointer,
      position: position,
      kind: PointerDeviceKind.mouse,
      timeStamp: tEnd,
    ),
  );
  binding.handlePointerEvent(
    PointerRemovedEvent(
      pointer: pointer,
      position: position,
      kind: PointerDeviceKind.mouse,
      timeStamp: tEnd,
    ),
  );

  return _ok({'ended': true, 'pointer': pointer});
}

